using Alterverse.Combat;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionPlanetDirector:MonoBehaviour
{
private const float FirstSpawn=120f,SecondSpawn=330f,ThirdSpawn=510f,Warning=15f;private static DimensionPlanetDirector active;private float elapsed;private bool warnedFirst,warnedSecond,warnedThird,spawnedFirst,spawnedSecond,spawnedThird;private DimensionsFront front;public static string Announcement{get;private set;}public static float AnnouncementUntil{get;private set;}public static float FirstSpawnRemaining=>Mathf.Max(0,FirstSpawn-(active!=null?active.elapsed:FirstSpawn));public static float SecondSpawnRemaining=>Mathf.Max(0,SecondSpawn-(active!=null?active.elapsed:SecondSpawn));public static float ThirdSpawnRemaining=>Mathf.Max(0,ThirdSpawn-(active!=null?active.elapsed:ThirdSpawn));private void Awake(){active=this;elapsed=0;warnedFirst=warnedSecond=warnedThird=spawnedFirst=spawnedSecond=spawnedThird=false;Announcement=null;AnnouncementUntil=0;front=FindAnyObjectByType<DimensionsFront>();}private void OnDestroy(){if(active==this){active=null;Announcement=null;AnnouncementUntil=0;}}
private void Update(){if(Time.timeScale<=0f)return;if(front==null)front=FindAnyObjectByType<DimensionsFront>();if(front!=null&&front.HasEnded)return;elapsed+=Time.deltaTime;if(!warnedFirst&&elapsed>=FirstSpawn-Warning){warnedFirst=true;Announce("FLUX PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedFirst&&elapsed>=FirstSpawn){spawnedFirst=true;SpawnPlanet("DF_FluxPlanet",new Vector3(0,1.25f,3.2f),PlanetBuffType.Flux,320,StylizedArtDirection.LumenEnergy);Announce("FLUX PLANET ACTIVE — CENTER FRONT");}if(!warnedSecond&&elapsed>=SecondSpawn-Warning){warnedSecond=true;Announce("GUARD PLANET IN 15 SECONDS — METEOR STORM • CENTER FRONT");}if(!spawnedSecond&&elapsed>=SecondSpawn){spawnedSecond=true;SpawnPlanet("DF_GuardPlanet",new Vector3(0,1.25f,-3.2f),PlanetBuffType.Guard,900,StylizedArtDirection.WarmAccent);Announce("GUARD PLANET ACTIVE — METEOR SHOWER • WATCH THE IMPACT ZONES");}if(!warnedThird&&elapsed>=ThirdSpawn-Warning){warnedThird=true;Announce("FINAL FLUX PLANET SPAWNS IN 15 SECONDS — CENTER FRONT");}if(!spawnedThird&&elapsed>=ThirdSpawn){spawnedThird=true;SpawnPlanet("DF_FinalFluxPlanet",new Vector3(0,1.25f,10f),PlanetBuffType.Flux,460,StylizedArtDirection.LumenEnergy);Announce("FINAL FLUX PLANET ACTIVE — CENTER FRONT");}}
private static void Announce(string text){Announcement=text;AnnouncementUntil=Time.unscaledTime+4f;}private static void SpawnPlanet(string name,Vector3 p,PlanetBuffType type,float hp,Color color){GameObject root=GameObject.CreatePrimitive(PrimitiveType.Sphere);root.name=name;GameObject world=GameObject.Find("DF_MatchWorld");if(world!=null)root.transform.SetParent(world.transform,true);root.transform.position=p;root.transform.localScale=Vector3.one*1.65f;Renderer r=root.GetComponent<Renderer>();if(r!=null)r.material.color=Color.Lerp(color,Color.black,.18f);GameObject atmosphere=GameObject.CreatePrimitive(PrimitiveType.Sphere);atmosphere.name="DF_PlanetAtmosphere";atmosphere.transform.SetParent(root.transform,false);atmosphere.transform.localScale=Vector3.one*1.16f;Collider ac=atmosphere.GetComponent<Collider>();if(ac!=null)ac.enabled=false;Renderer ar=atmosphere.GetComponent<Renderer>();if(ar!=null)ar.material.color=new Color(color.r,color.g,color.b,.34f);GameObject ring=GameObject.CreatePrimitive(PrimitiveType.Cylinder);ring.name="DF_PlanetRing";ring.transform.SetParent(root.transform,false);ring.transform.localScale=new Vector3(1.85f,.035f,1.85f);ring.transform.localRotation=Quaternion.Euler(type==PlanetBuffType.Guard?68f:74f,0,18f);Collider rc=ring.GetComponent<Collider>();if(rc!=null)rc.enabled=false;Renderer rr=ring.GetComponent<Renderer>();if(rr!=null)rr.material.color=Color.Lerp(color,Color.white,.35f);for(int i=0;i<8;i++){GameObject shard=GameObject.CreatePrimitive(i%2==0?PrimitiveType.Cube:PrimitiveType.Sphere);shard.name="DF_PlanetShard";shard.transform.SetParent(root.transform,false);float a=i*Mathf.PI*.25f;float orbit=1.45f+(i%3)*.12f;shard.transform.localPosition=new Vector3(Mathf.Cos(a)*orbit,Mathf.Sin(i*1.7f)*.42f,Mathf.Sin(a)*orbit);shard.transform.localScale=i%2==0?new Vector3(.12f,.48f,.12f):Vector3.one*.18f;shard.transform.rotation=Quaternion.Euler(25,i*47,25);Collider c=shard.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer sr=shard.GetComponent<Renderer>();if(sr!=null)sr.material.color=color;}GameObject core=GameObject.CreatePrimitive(PrimitiveType.Sphere);core.name="DF_PlanetCore";core.transform.SetParent(root.transform,false);core.transform.localScale=Vector3.one*.46f;Collider cc=core.GetComponent<Collider>();if(cc!=null)cc.enabled=false;Renderer cr=core.GetComponent<Renderer>();if(cr!=null)cr.material.color=Color.Lerp(color,Color.white,.62f);Health h=root.AddComponent<Health>();h.Configure(hp);DimensionPlanet planet=root.AddComponent<DimensionPlanet>();planet.Initialize(type);PlanetPulseAttack pulse=root.AddComponent<PlanetPulseAttack>();if(type==PlanetBuffType.Guard){pulse.enabled=false;root.AddComponent<PlanetMeteorShower>();}}
}
}
